const supportedLanguages = languageOptions.map((option) => option.value)

function normalizeLanguage(language: string | undefined): AppLanguage {
	return supportedLanguages.includes(language as AppLanguage) ? (language as AppLanguage) : 'zh-Hans'
}

let currentLanguage = normalizeLanguage(getSettings().language)

export function getLanguage(): AppLanguage {
	return currentLanguage
}

export function setLanguage(language: AppLanguage) {
	currentLanguage = normalizeLanguage(language)
	const settings = getSettings()
	saveSettings({
		...settings,
		language: currentLanguage
	})
}

export function syncLanguage() {
	currentLanguage = normalizeLanguage(getSettings().language)
	return currentLanguage
}

export function t(key: I18nKey): string {
	const language = normalizeLanguage(currentLanguage)
	const overrideMessages = localeOverrides[language] || {}
	const complementMessages = localeComplements[language] || {}
	const languageMessages = ((messages as Partial<Record<AppLanguage, Partial<Record<I18nKey, string>>>>)[language] || {}) as Partial<Record<I18nKey, string>>
	return complementMessages[key] || overrideMessages[key] || languageMessages[key] || messages.en[key] || messages['zh-Hans'][key] || key
}

export function recordTypeLabel(type: string): string {
	const map: Record<string, I18nKey> = {
		WiFi: 'wifiQr',
		名片: 'contact',
		链接: 'link',
		文本: 'text',
		扫码: 'scan'
	}
	return t(map[type] || 'text')
}
